import{_ as e,o as a,c as s,ae as n}from"./chunks/framework.B2ul6ABY.js";const g=JSON.parse('{"title":"Card Lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"historical/2026-pre-consolidation/02-card-lifecycle.md","filePath":"historical/2026-pre-consolidation/02-card-lifecycle.md"}'),i={name:"historical/2026-pre-consolidation/02-card-lifecycle.md"};function d(r,t,l,o,c,h){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="card-lifecycle" tabindex="-1">Card Lifecycle <a class="header-anchor" href="#card-lifecycle" aria-label="Permalink to &quot;Card Lifecycle&quot;">​</a></h1><h2 id="states" tabindex="-1">States <a class="header-anchor" href="#states" aria-label="Permalink to &quot;States&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td>drafting</td><td>Being shaped by analyst + user/planner. Not yet actionable.</td></tr><tr><td>backlog</td><td>Fully specified, waiting to be picked up.</td></tr><tr><td>active</td><td>Assigned to the runtime, preparing to run.</td></tr><tr><td>running</td><td>Executor is working (scripts, training, etc.).</td></tr><tr><td>blocked</td><td>Waiting on a dependency or user input.</td></tr><tr><td>done</td><td>Completely done. A task is done when its executor says it is done; a goal is done only after reviewer pass.</td></tr><tr><td>failed</td><td>Completed with errors.</td></tr><tr><td>cancelled</td><td>Abandoned.</td></tr></tbody></table><hr><h2 id="transitions" tabindex="-1">Transitions <a class="header-anchor" href="#transitions" aria-label="Permalink to &quot;Transitions&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stateDiagram-v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    [*] --&gt; drafting: create</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    drafting --&gt; backlog: analyst approves / user confirms</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    backlog --&gt; active: runtime picks</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    active --&gt; running: execution starts</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    running --&gt; done: success</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    running --&gt; failed: error</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    running --&gt; blocked: waiting</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    blocked --&gt; running: unblock / retry</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    done --&gt; backlog: reopen</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    failed --&gt; backlog: reopen</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    drafting --&gt; cancelled</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    backlog --&gt; cancelled</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    active --&gt; cancelled</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    running --&gt; cancelled</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    blocked --&gt; cancelled</span></span></code></pre></div><p>Any non-terminal state → <code>cancelled</code>.</p><hr><h2 id="global-pause" tabindex="-1">Global Pause <a class="header-anchor" href="#global-pause" aria-label="Permalink to &quot;Global Pause&quot;">​</a></h2><p>Pause is <strong>global</strong>, not per card/task. A global runtime pause stops new planner, executor, and reviewer dispatch. It does not change individual card state and does not automatically kill already-running external processes.</p><p>While paused:</p><ul><li>No new agent sessions are started.</li><li>Already-running processes continue unless explicitly killed.</li><li>The analyst remains available for inspection and card management.</li><li>Resume restores normal dispatch from the current queue position.</li></ul><hr><h2 id="permissions-by-state" tabindex="-1">Permissions by State <a class="header-anchor" href="#permissions-by-state" aria-label="Permalink to &quot;Permissions by State&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Card editable?</th><th>Notes editable?</th><th>Executor works?</th><th>User can…</th></tr></thead><tbody><tr><td>drafting</td><td>yes</td><td>yes (all)</td><td>no</td><td>edit everything, delete card</td></tr><tr><td>backlog</td><td>yes</td><td>yes (unhandled)</td><td>no</td><td>reprioritize, edit, add notes</td></tr><tr><td>active</td><td>no</td><td>yes (unhandled)</td><td>preparing</td><td>add directives, cancel</td></tr><tr><td>running</td><td>no</td><td>yes (unhandled)</td><td>yes</td><td>add directives, cancel</td></tr><tr><td>blocked</td><td>no</td><td>yes (unhandled)</td><td>waiting</td><td>unblock, add notes, cancel</td></tr><tr><td>done</td><td>no</td><td>no</td><td>no</td><td>reopen → backlog</td></tr><tr><td>failed</td><td>no</td><td>no</td><td>no</td><td>retry → backlog, cancel</td></tr><tr><td>cancelled</td><td>no</td><td>no</td><td>no</td><td>reopen → drafting</td></tr></tbody></table><hr><h2 id="views-over-the-card-tree" tabindex="-1">Views over the Card Tree <a class="header-anchor" href="#views-over-the-card-tree" aria-label="Permalink to &quot;Views over the Card Tree&quot;">​</a></h2><p>The leaderboard is not a separate data structure. It is a <strong>query</strong> over the card tree:</p><blockquote><p>Show all <code>done</code> result cards sorted by a chosen metric.</p></blockquote><p>The web UI renders this as a sortable table. Each row links to the result card with full details, sub-tasks, attachments, execution logs, etc.</p><p>Different views:</p><ul><li><strong>Leaderboard</strong>: done result cards, sorted by metric.</li><li><strong>Board</strong>: kanban-style columns (backlog / active / done / failed).</li><li><strong>Tree</strong>: hierarchical view of all cards.</li><li><strong>Timeline</strong>: Gantt-style view of card durations.</li></ul>`,22)])])}const k=e(i,[["render",d]]);export{g as __pageData,k as default};
